package vn.edu.eaut.lab7.controller;import jakarta.servlet.*;import jakarta.servlet.annotation.*;import jakarta.servlet.http.*;import java.io.*;import vn.edu.eaut.lab7.repository.*;@WebServlet("/admin/dashboard")public class DashboardServlet extends HttpServlet{protected void doGet(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{q.setAttribute("sv",new SinhVienRepository().findAll().size());q.setAttribute("sach",new SachRepository().findAll().size());q.setAttribute("sp",new SanPhamRepository().findAll().size());q.getRequestDispatcher("/views/dashboard.jsp").forward(q,p);}}
